import{_ as i,l as r,o as t,c as s,v as e,p as l,x as n,d as E,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"垂直差异","description":"","frontmatter":{"title":"垂直差异","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/vertical-differentiation.md","filePath":"econ/vertical-differentiation.md","lastUpdated":1789023840000}'),p={name:"econ/vertical-differentiation.md"};function c(u,a,S,_,A,B){const o=r("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="垂直差异" tabindex="-1">垂直差异 <a class="header-anchor" href="#垂直差异" aria-label="Permalink to &quot;垂直差异&quot;">​</a></h1><div class="epigraph"><p>若人人同意谁的质量更高，只是对加价的忍受不同，竞争的是质量阶梯，不是街道上的地址，也不是对称 CES 品种。</p><footer>—— 据 Shaked and Sutton, Relaxing Price Competition Through Product Differentiation, RES, 1982；Mussa and Rosen, Monopoly and Product Quality, JET, 1978 整理</footer></div><p>定位：<a href="/econ/monopolistic-dixit-stiglitz">上一课</a>。Dixit–Stiglitz 的品种在质量上对称，差异来自种类爱。本课不重讲 CES 与内生 \\(n\\) 的零利润算术。<a href="/econ/hotelling">霍特林</a>的横差异是「有人喜欢左、有人喜欢右」。缺口是纵差异：所有人的排序一致，\\(u=\\theta s-p\\)，只是 \\(\\theta\\) 不同。质量高低不是把 \\([0,1]\\) 再画一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>消费者类型 \\(\\theta\\) 分布在区间上，质量 \\(s\\) 越高越好。买不买、买哪一档，由净效用 \\(\\theta s-p\\) 的上包络决定。两家若选 \\(s_H\\gt s_L\\) 再定价，市场按 \\(\\theta\\) 切开，高 \\(\\theta\\) 买高质。缺口不是再写一次勒纳，而是：<strong>质量选择如何软化价格竞争，以及市场变大时均衡家数会不会像 DS 那样无限增加。</strong></p><p>Shaked–Sutton：质量提升若主要靠固定成本（研发），价格竞争在质量拉开之后变钝，但市场扩大时高质厂商能覆盖全市场，低质被挤出——<strong>自然寡头</strong>：即使 \\(F\\) 相对市场规模趋于零，\\(n\\) 仍有上界。这与 DS 的「市场越大 \\(n\\) 越大」相反，不要把两课的进入写成同一条。</p><h3 id="纵差异不是霍特林的「上北下南」" tabindex="-1">纵差异不是霍特林的「上北下南」 <a class="header-anchor" href="#纵差异不是霍特林的「上北下南」" aria-label="Permalink to &quot;纵差异不是霍特林的「上北下南」&quot;">​</a></h3><p>把质量画在纵轴上很容易误读成另一条线性城市。横差异：无差异消费者两边都有正密度，两家往中间挤或往两端走，取决于运费。纵差异：排序一致，低质要活下去必须够便宜，质量差距本身就是策略。Mussa–Rosen 处理的是一家垄断者对连续 \\(\\theta\\) 提供质量菜单，类似二级歧视，不是选址。</p><p><span class="marginnote">自然寡头的关键是：质量的边际成本不要升得太快。若高质量主要吃可变成本，低质仍有空间，家数可以随市场扩张。Shaked–Sutton 强调的是固定成本型质量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段：先选 \\(s_i\\)，再选 \\(p_i\\)。价格阶段用 \\(\\theta\\) 的切开条件求份额，再逆向归纳质量。覆盖还是排除最低 \\(\\theta\\)，取决于质量成本与 \\(\\theta\\) 的下界。垄断菜单（Mussa–Rosen）：对 \\(\\theta\\) 的激励相容给出质量扭曲——低类型质量向下扭曲、最高类型有效，与<a href="/econ/screening-rent">筛选</a>同构，本课只点接口，不把信息租金再推一遍。</p><p>进入：给定质量技术，问均衡有限 \\(n\\) 是否对市场规模一致有界。这是与上一课 CES 进入的对照实验，不是把 \\(F\\) 再除一次。</p><p>三家以上时，最低质量档更容易被「从上面」覆盖挤出。自然寡头的上界来自质量竞争的这个方向，不是来自固定成本相对市场的简单除法。</p>',13)),(t(),l(d,null,{default:n(()=>[h(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DS%5B%22DS%EF%BC%9A%E5%AF%B9%E7%A7%B0%E5%93%81%E7%A7%8D%EF%BC%8Cn%20%E9%9A%8F%E5%B8%82%E5%9C%BA%E5%8D%87%22%5D%20--%3E%20VERT%5B%22%E4%BA%BA%E4%BA%BA%E5%90%8C%E6%84%8F%E8%B4%A8%E9%87%8F%E6%8E%92%E5%BA%8F%22%5D%0A%20%20HOT%5B%22%E9%9C%8D%E7%89%B9%E6%9E%97%EF%BC%9A%E5%8F%A3%E5%91%B3%E7%9B%B8%E5%8F%8D%22%5D%20--%3E%20VERT%0A%20%20VERT%20--%3E%20SS%5B%22Shaked%E2%80%93Sutton%EF%BC%9A%E8%B4%A8%E9%87%8F%E6%8B%89%E5%BC%80%20%2B%20%E8%87%AA%E7%84%B6%E5%AF%A1%E5%A4%B4%22%5D%0A%20%20VERT%20--%3E%20MR%5B%22Mussa%E2%80%93Rosen%EF%BC%9A%E5%9E%84%E6%96%AD%E8%B4%A8%E9%87%8F%E8%8F%9C%E5%8D%95%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不要把「高质高价」写成限价簿上档位更深；这里没有队列。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>软化价格竞争的机制是：质量差距降低交叉弹性，高 \\(\\theta\\) 不愿为了省钱掉到低质，低质不能靠小幅降价抢走全部市场——有点像霍特林的 \\(t\\)，但 \\(t\\) 两边对称，质量阶梯不对称。自然寡头的机制是：市场一扩大，高质厂商降价覆盖的激励增强，低质的生存空间被「从上面」吃掉，而不是被对称的新品种稀释。</p><p>与 DS 的分工：需要「目录里多种可替代的同类」时用 CES；需要「大家认的好坏、收入或 \\(\\theta\\) 分层」时用纵差异。同一行业可以两种都在，本课禁止把质量写成 CES 的另一个 \\(i\\)。</p><p>覆盖决策也是一刀：若最低 \\(\\theta\\) 被排除，低质厂商面对的是截断的需求，质量选择更极端；若必须覆盖，低质变成「买得起的那一档」，与霍特林两端的「最大差异」只在表面上像。收入分布一变，\\(\\theta\\) 的密度改切开点，均衡质量阶梯跟着移——这是分配，不是运费 \\(t\\)。</p><p><span class="marginnote">Mussa–Rosen 1978 是垄断者的质量歧视；Shaked–Sutton 1982/1983 是寡头质量竞争与自然寡头。不要把垄断菜单的「顶部无扭曲」写成寡头均衡性质。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>广告、品牌作为横差异与纵差异的混合物，本课不拆。经验品、声誉使 \\(s\\) 不可事前观察，接到信号课。规制最低质量标准会切掉 \\(s_L\\)，改变自然寡头的数目。也不要把收入分层直接写成三级歧视的组标签：\\(\\theta\\) 通常不可观察，质量菜单是自选，不是按身份证定价。</p><p>限价簿的档位深浅不是质量 \\(s\\)。</p><p>市场结构课序在此收束纵差异。一般均衡下一课程用盒子读配置，不再加一家商店的质量阶梯。后课默认：纵差异是一致排序加 \\(\\theta\\) 异质；不要用本课重讲霍特林端点或 CES 种类爱。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>质量排序一致，\\(\\theta\\) 决定谁买哪一档；不是横选址，不是对称 CES。</li><li>质量差距软化价格战；固定成本型质量可给出自然寡头。</li><li>垄断质量菜单是二级歧视，顶部有效、下部扭曲。</li><li>下一课程换坐标系：从局部产品市场进入交换的盒子。</li><li>出处：Shaked and Sutton, <em>RES</em>, 1982；Mussa and Rosen, <em>JET</em>, 1978。</li></ul>',12))])}const C=i(p,[["render",c]]);export{m as __pageData,C as default};
